// Generate README, gitignore, token lists and slugs — sinh README, gitignore, token list và slug.
// Common generated project text and token helpers.
use super::*;

pub(in crate::scaffold::processor) fn common_readme(
    name: &str,
    core: &str,
    framework: &str,
    features: &[String],
) -> String {
    let mut out = format!(
        "# {}\n\nGenerated by MagiCore.\n\n- Core: `{}`\n- Framework: `{}`\n",
        name, core, framework
    );
    if !features.is_empty() {
        out.push_str(&format!("- Features: `{}`\n", features.join("`, `")));
    }
    let next_step = if features.iter().any(|feature| feature == "docker") {
        "Run `mgc install` in this directory to create the project lockfile, then run `docker compose up --build`. The image copies that same lock and uses `mgc install --frozen`; dependency resolution and lifecycle remain identical between the host project and container."
    } else {
        "Run `mgc install` in this directory; MagiCore detects the core from `mgc.toml` and `.mgc.core`."
    };
    out.push_str(&format!("\n## Next\n\n{next_step}\n"));
    out
}
pub(in crate::scaffold::processor) fn quoted_list(values: &[String]) -> String {
    values
        .iter()
        .map(|value| format!("\"{}\"", value))
        .collect::<Vec<_>>()
        .join(", ")
}
pub(in crate::scaffold::processor) fn config_feature_set(raw: &str) -> HashSet<&str> {
    raw.split(',')
        .map(|part| part.trim())
        .filter(|part| !part.is_empty())
        .map(|part| part.trim_matches('"'))
        .filter(|part| !part.is_empty())
        .collect()
}
pub(in crate::scaffold::processor) fn extract_template_tokens(input: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let mut rest = input;

    while let Some(start) = rest.find("{{") {
        let after_start = &rest[start + 2..];
        let Some(end) = after_start.find("}}") else {
            break;
        };
        let token = after_start[..end].trim();
        if !token.is_empty() && !tokens.iter().any(|existing| existing == token) {
            tokens.push(token.to_string());
        }
        rest = &after_start[end + 2..];
    }

    tokens
}
pub(in crate::scaffold::processor) fn common_gitignore(core: &str, framework: &str) -> String {
    let mut lines = vec![
        ".DS_Store",
        ".magicore/cache",
        ".magicore/tmp",
        ".env",
        ".env.local",
    ];

    match core {
        "web" => lines.extend(["node_modules", "dist", ".next", ".svelte-kit"]),
        "game" => {
            if framework == "unity" {
                lines.extend(["Library", "Temp", "Build"]);
            } else if framework == "godot" {
                lines.extend([".godot", ".import"]);
            } else {
                lines.push("target");
            }
        }
        "ai" => lines.extend([".venv", "__pycache__", ".pytest_cache"]),
        "clo" => lines.extend([".pulumi", ".terraform", ".terraform.lock.hcl"]),
        "cicd" => lines.extend([".artifacts", ".secrets"]),
        "iot" => lines.extend([".pio", "target", "build"]),
        "app" => lines.extend([".dart_tool", "build", ".gradle", ".build"]),
        "lib" => lines.extend(["target", "dist", "__pycache__"]),
        _ => {}
    }

    lines.join("\n") + "\n"
}
pub(in crate::scaffold) fn slugify(name: &str) -> String {
    let mut slug = String::with_capacity(name.len());
    for ch in name.chars() {
        if ch.is_ascii_alphanumeric() {
            slug.push(ch.to_ascii_lowercase());
        } else if matches!(ch, '-' | '_' | ' ') && !slug.ends_with('-') {
            slug.push('-');
        }
    }

    let trimmed = slug.trim_matches('-');
    if trimmed.is_empty() {
        "magicore-project".to_string()
    } else {
        trimmed.to_string()
    }
}
